WITH scored AS (SELECT id, city, opened_date, sqft, NTILE(10) OVER (PARTITION BY city ORDER BY sqft DESC, id) AS sqft_bucket, AVG(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sqft_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY city ORDER BY sqft, id) AS row_seq FROM stores), valid AS (SELECT id, city, opened_date, sqft, sqft_bucket, CASE WHEN sqft_bucket >= 8 THEN 'High' WHEN sqft_bucket >= 3 THEN 'Medium' ELSE 'Low' END AS sqft_bucket_tier FROM scored WHERE opened_date > DATE '2023-04-16'), base AS (SELECT *, LENGTH(city) AS city_length FROM valid WHERE opened_date > DATE '2023-07-30' AND YEAR(opened_date) = 2023), with_last AS (SELECT s.id, s.sqft, s.sqft_bucket, s.sqft_bucket_tier, s.city_length, x.store_sale_units, x.store_sale_sale_date FROM base s LEFT JOIN LATERAL (SELECT c.units AS store_sale_units, c.sale_date AS store_sale_sale_date FROM store_sales c WHERE c.store_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, store_sale_units, AVG(store_sale_units) OVER (ORDER BY city_length, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS store_sale_units_avg_6, DENSE_RANK() OVER (ORDER BY city_length) AS city_length_dense_rank, NTILE(3) OVER (ORDER BY sqft_bucket DESC, id) AS sqft_bucket_bucket FROM with_last
